/**
 * D11 Runtime Repository Events: four weeks of activity on fictional open-source repositories, generated by Runtime
 * in the shape of the public GitHub event stream (as archived by GH Archive): one JSON object per line, one file per
 * hour or day, nested actor / repo / payload objects that differ by event type.
 *
 * Generated instead of acquired: archived GitHub events carry real people's logins and commit e-mail addresses.
 * Every account, repository, commit and issue here is invented, and e-mail addresses use the reserved example.com
 * domain. The stream's real-world awkwardness is kept: bots, bursts, events out of order inside a file, an event
 * repeated in two files, payload fields that only some types have.
 */
import { createRng, ts, ms, DAY, HOUR } from '../../lib/rng.mjs';

const SEED = 20261111;
const col = (name, type, description, nullable = false) => ({ name, type, description, nullable });
const START = ms('2025-03-03');
const DAYS = 28;
const ORGS = ['quill-data', 'tidewater', 'lumen-labs', 'pyforge', 'nimbus-io', 'orchard-dev', 'brightpath', 'cobalt-tools', 'meridian-ai', 'sparrow-web'];
const REPO_A = ['fast', 'tiny', 'py', 'data', 'stream', 'easy', 'open', 'deep', 'micro', 'auto', 'graph', 'cloud', 'quick', 'smart', 'meta'];
const REPO_B = ['parser', 'cache', 'frame', 'router', 'sync', 'lint', 'plot', 'queue', 'auth', 'docs', 'cli', 'etl', 'store', 'shell', 'test', 'vector', 'flow', 'kit'];
const LANGS = [['Python', 40], ['TypeScript', 18], ['JavaScript', 10], ['Rust', 9], ['Go', 9], ['Java', 4], ['C++', 3], ['Jupyter Notebook', 4], [null, 3]];
const WORDS = ['fix', 'add', 'update', 'remove', 'refactor', 'improve', 'bump', 'docs:', 'test:', 'feat:', 'chore:', 'perf:'];
const THINGS = ['parser edge case', 'README examples', 'type hints', 'CI workflow', 'cache invalidation', 'error message', 'dependency versions', 'unicode handling', 'retry logic', 'CLI flags', 'memory leak', 'flaky test', 'pagination', 'timezone bug', 'logging format', 'config loading'];
const LABELS = ['bug', 'enhancement', 'documentation', 'good first issue', 'help wanted', 'question', 'duplicate', 'wontfix', 'performance'];
const TYPES = [['PushEvent', 46], ['WatchEvent', 13], ['PullRequestEvent', 9], ['IssueCommentEvent', 9], ['CreateEvent', 8], ['IssuesEvent', 5], ['DeleteEvent', 3], ['ForkEvent', 3], ['PullRequestReviewEvent', 3], ['ReleaseEvent', 1]];
const HOURS = [2, 1.6, 1.4, 1.3, 1.4, 1.8, 2.4, 3.2, 4.2, 5, 5.5, 5.8, 5.8, 6, 6.2, 6.4, 6.2, 5.8, 5, 4.4, 4, 3.6, 3, 2.4];

const hex = (r, n) => Array.from({ length: n }, () => '0123456789abcdef'[r.int(0, 15)]).join('');
const iso = t => new Date(t).toISOString().replace('.000Z', 'Z');

function generate() {
  const rng = createRng(SEED);
  const aRng = rng.fork('actors');
  const actors = [];
  for (let i = 1; i <= 1400; i++) {
    const login = `${aRng.pick(['dev', 'code', 'py', 'data', 'byte', 'stack', 'null', 'git', 'hack', 'ml'])}${aRng.pick(['-', '_', ''])}${aRng.pick(['otter', 'fox', 'owl', 'lynx', 'wren', 'yak', 'koi', 'elk', 'ant', 'bee', 'ray'])}${aRng.int(1, 999)}`;
    actors.push({ actor_id: 10_000_000 + i * 71, login, is_bot: 0, _w: aRng.lognormal(1, 1.3) });
  }
  for (const b of ['dependabot[bot]', 'renovate[bot]', 'github-actions[bot]', 'pre-commit-ci[bot]']) actors.push({ actor_id: 49_000_000 + actors.length, login: b, is_bot: 1, _w: 6 });
  const rRng = rng.fork('repos');
  const repos = [];
  const names = new Set();
  while (repos.length < 320) {
    const name = `${rRng.pick(ORGS)}/${rRng.pick(REPO_A)}${rRng.pick(['', '-'])}${rRng.pick(REPO_B)}`;
    if (names.has(name)) continue;
    names.add(name);
    repos.push({ repo_id: 600_000_000 + repos.length * 997, name, owner: name.split('/')[0], language: rRng.weighted(LANGS), created_at: ts(ms('2016-01-01') + rRng.int(0, 3200) * DAY), stars_before: Math.round(rRng.lognormal(120, 1.8)), _w: rRng.lognormal(1, 1.4) });
  }
  const pick = (list, r) => { let s = 0; for (const x of list) s += x._w; let v = r.next() * s; for (const x of list) { v -= x._w; if (v < 0) return x; } return list.at(-1); };

  const eRng = rng.fork('events');
  const events = [];
  const issues = new Map();
  let seq = 0;
  for (let d = 0; d < DAYS; d++) {
    const dow = new Date(START + d * DAY).getUTCDay();
    const perDay = Math.round((dow === 0 || dow === 6 ? 560 : 1150) * eRng.lognormal(1, 0.12));
    for (let k = 0; k < perDay; k++) {
      const hour = eRng.weighted(HOURS.map((w, h) => [h, w]));
      const t = START + d * DAY + hour * HOUR + eRng.int(0, 3599) * 1000;
      const type = eRng.weighted(TYPES);
      const repo = pick(repos, eRng);
      let actor = pick(actors, eRng);
      if (type !== 'PushEvent' && type !== 'PullRequestEvent' && actor.is_bot) actor = actors[eRng.int(0, 1399)];
      const id = String(48_000_000_000 + ++seq * 7);
      const base = { id, type, actor: { id: actor.actor_id, login: actor.login, display_login: actor.login, url: `https://api.example.com/users/${actor.login}` }, repo: { id: repo.repo_id, name: repo.name, url: `https://api.example.com/repos/${repo.name}` }, payload: {}, public: true, created_at: iso(t) };
      if (eRng.chance(0.85)) base.org = { id: 9_000_000 + ORGS.indexOf(repo.owner), login: repo.owner };
      const p = base.payload;
      const iss = issues.get(repo.repo_id) ?? issues.set(repo.repo_id, { next: eRng.int(10, 900) }).get(repo.repo_id);
      if (type === 'PushEvent') {
        const n = actor.is_bot ? 1 : Math.max(1, Math.min(20, Math.round(eRng.lognormal(1.6, 0.8))));
        Object.assign(p, { repository_id: repo.repo_id, push_id: 23_000_000_000 + seq, size: n, distinct_size: eRng.chance(0.93) ? n : Math.max(0, n - 1), ref: eRng.chance(0.7) ? 'refs/heads/main' : `refs/heads/${eRng.pick(['dev', 'feature/' + eRng.pick(REPO_B), 'fix/' + eRng.pick(REPO_B)])}`, head: hex(eRng, 40), before: hex(eRng, 40) });
        p.commits = Array.from({ length: n }, () => ({ sha: hex(eRng, 40), author: { email: `${actor.login.replace(/\[bot\]/, '')}@users.example.com`, name: actor.login }, message: actor.is_bot ? `Bump ${eRng.pick(REPO_B)} from 1.${eRng.int(0, 9)}.${eRng.int(0, 9)} to 1.${eRng.int(0, 9)}.${eRng.int(0, 9)}` : `${eRng.pick(WORDS)} ${eRng.pick(THINGS)}${eRng.chance(0.2) ? `\n\nCloses #${eRng.int(1, iss.next)}` : ''}`, distinct: true }));
      } else if (type === 'WatchEvent') p.action = 'started';
      else if (type === 'ForkEvent') p.forkee = { id: 700_000_000 + seq, full_name: `${actors[eRng.int(0, 1399)].login}/${repo.name.split('/')[1]}`, fork: true, created_at: iso(t) };
      else if (type === 'CreateEvent' || type === 'DeleteEvent') Object.assign(p, { ref: type === 'CreateEvent' && eRng.chance(0.05) ? null : `${eRng.pick(['feature', 'fix', 'docs'])}/${eRng.pick(THINGS).replace(/ /g, '-')}`, ref_type: type === 'CreateEvent' && eRng.chance(0.05) ? 'repository' : eRng.chance(0.9) ? 'branch' : 'tag', pusher_type: 'user', ...(type === 'CreateEvent' ? { master_branch: 'main', description: null } : {}) });
      else if (type === 'IssuesEvent') {
        const action = eRng.weighted([['opened', 55], ['closed', 38], ['reopened', 4], ['labeled', 3]]);
        const number = action === 'opened' ? iss.next++ : eRng.int(1, Math.max(1, iss.next - 1));
        p.action = action;
        p.issue = { number, title: `${eRng.pick(['Error when', 'Support', 'Docs: clarify', 'Crash on', 'Feature request:', 'Slow'])} ${eRng.pick(THINGS)}`, state: action === 'closed' ? 'closed' : 'open', labels: eRng.chance(0.6) ? [...new Set([eRng.pick(LABELS), ...(eRng.chance(0.3) ? [eRng.pick(LABELS)] : [])])].map(name => ({ name })) : [], comments: eRng.poisson(2), created_at: iso(t - (action === 'opened' ? 0 : eRng.int(1, 300) * HOUR)), closed_at: action === 'closed' ? iso(t) : null };
      } else if (type === 'IssueCommentEvent') {
        p.action = 'created';
        p.issue = { number: eRng.int(1, Math.max(1, iss.next - 1)), title: `${eRng.pick(['Error when', 'Support', 'Crash on'])} ${eRng.pick(THINGS)}`, state: eRng.chance(0.7) ? 'open' : 'closed' };
        p.comment = { id: 2_700_000_000 + seq, body: eRng.pick(['Thanks! Looking into it.', 'Can you share a minimal example?', '+1', 'Same here on 3.12.', 'Fixed in main, will release soon.', 'Duplicate of #' + eRng.int(1, 500), 'LGTM 👍']), created_at: iso(t) };
      } else if (type === 'PullRequestEvent' || type === 'PullRequestReviewEvent') {
        const action = type === 'PullRequestReviewEvent' ? 'created' : eRng.weighted([['opened', 52], ['closed', 44], ['reopened', 2], ['synchronize', 2]]);
        const merged = action === 'closed' && eRng.chance(0.78);
        p.action = action;
        p.number = eRng.int(1, iss.next + 200);
        p.pull_request = { number: p.number, title: actor.is_bot ? `Bump ${eRng.pick(REPO_B)} to 2.${eRng.int(0, 20)}.${eRng.int(0, 9)}` : `${eRng.pick(WORDS)} ${eRng.pick(THINGS)}`, state: action === 'closed' ? 'closed' : 'open', merged, additions: Math.round(eRng.lognormal(40, 1.4)), deletions: Math.round(eRng.lognormal(12, 1.4)), changed_files: Math.max(1, Math.round(eRng.lognormal(3, 1))), created_at: iso(t - (action === 'opened' ? 0 : eRng.int(1, 200) * HOUR)), merged_at: merged ? iso(t) : null };
        if (type === 'PullRequestReviewEvent') p.review = { id: 1_900_000_000 + seq, state: eRng.weighted([['approved', 60], ['commented', 30], ['changes_requested', 10]]), submitted_at: iso(t) };
      } else if (type === 'ReleaseEvent') {
        p.action = 'published';
        p.release = { tag_name: `v${eRng.int(0, 4)}.${eRng.int(0, 30)}.${eRng.int(0, 12)}`, name: null, prerelease: eRng.chance(0.15), draft: false, published_at: iso(t) };
      }
      events.push(base);
    }
  }
  events.sort((a, b) => (a.created_at < b.created_at ? -1 : a.created_at > b.created_at ? 1 : a.id.localeCompare(b.id)));
  const strip = o => Object.fromEntries(Object.entries(o).filter(([k]) => !k.startsWith('_')));
  return { events, actors: actors.map(strip), repos: repos.map(strip) };
}

/** Files as GH Archive writes them: by hour (starter) or by day, with collector jitter: a few events land late in a file. */
function streamFiles(events, by, seed) {
  const rng = createRng(seed);
  const files = new Map();
  for (const e of events) {
    const key = by === 'hour' ? e.created_at.slice(0, 13).replace('T', '-') : e.created_at.slice(0, 10);
    (files.get(key) ?? files.set(key, []).get(key)).push(e);
  }
  const out = [];
  for (const [key, list] of files) {
    const lines = list.slice();
    // A few events written out of order, and (rarely) one repeated at the start of the next file.
    for (let i = 0; i < Math.round(lines.length * 0.01); i++) { const a = rng.int(0, lines.length - 1), b = Math.min(lines.length - 1, a + rng.int(1, 6)); [lines[a], lines[b]] = [lines[b], lines[a]]; }
    out.push({ key, lines });
  }
  for (let i = 1; i < out.length; i++) if (rng.chance(0.3)) out[i].lines.unshift(out[i - 1].lines.at(-1));
  return out;
}

const EDITIONS = { preview: { days: 1, limit: 40, by: 'day' }, starter: { days: 1, by: 'hour' }, standard: { days: 7, by: 'day' }, full: { days: 28, by: 'day' } };

function flat(events) {
  return events.map(e => ({
    event_id: e.id, type: e.type, created_at: e.created_at.replace('T', ' ').replace('Z', ''), actor_id: e.actor.id, actor_login: e.actor.login, repo_id: e.repo.id, repo_name: e.repo.name,
    org: e.org?.login ?? null, action: e.payload.action ?? null, ref: e.payload.ref ?? null, commits: e.payload.size ?? null,
    number: e.payload.issue?.number ?? e.payload.number ?? null,
  }));
}

function cutEdition(full, edition) {
  const e = EDITIONS[edition];
  const last = new Date(START + e.days * DAY).toISOString();
  let events = full.events.filter(x => x.created_at < last);
  if (e.limit) events = events.slice(0, e.limit);
  const actorIds = new Set(events.map(x => x.actor.id));
  const repoIds = new Set(events.map(x => x.repo.id));
  return { events: flat(events), actors: full.actors.filter(a => actorIds.has(a.actor_id)), repos: full.repos.filter(r => repoIds.has(r.repo_id)), _raw: events };
}

function extraFiles(tables, edition) {
  const files = streamFiles(tables._raw, EDITIONS[edition].by, SEED + edition.length);
  delete tables._raw;
  return files.map(f => ({ path: `events/${f.key}.jsonl`, table: 'events', text: f.lines.map(x => JSON.stringify(x)).join('\n') + '\n', rows: f.lines.length }));
}

function realIssues({ events }) {
  return [
    { id: 'bots', description: 'Events by bot accounts (logins ending in [bot])', count: events.filter(e => e.actor_login.endsWith('[bot]')).length },
    { id: 'type_specific_payload', description: 'Event types whose payloads have different fields', count: new Set(events.map(e => e.type)).size },
    { id: 'repeated_across_files', description: 'Some files start with the last event of the previous file (deduplicate by id)', count: 1 },
    { id: 'out_of_order', description: 'Within a file, about 1% of events are slightly out of time order', count: 1 },
  ];
}

const dataset = {
  id: 'D11',
  title: 'Runtime Repository Events',
  version: 1,
  seed: SEED,
  description:
    'Four weeks of activity on fictional open-source repositories, in the shape of the public GitHub event stream: ' +
    'pushes, stars, pull requests, issues, comments and releases, one JSON object per line in hourly or daily files. ' +
    'Generated by Runtime; every account and repository is invented.',
  licence: { name: 'Runtime-owned synthetic data', status: 'ours' },
  generator: 'datasets/python/D11/dataset.mjs',
  window: ['2025-03-03', '2025-03-30'],
  tables: {
    events: {
      description: 'One event per row: the fields every event has, plus a few common details.',
      primaryKey: ['event_id'],
      foreignKeys: [{ column: 'actor_id', references: 'actors.actor_id' }, { column: 'repo_id', references: 'repos.repo_id' }],
      columns: [
        col('event_id', 'text', 'Event ID'), col('type', 'text', 'PushEvent, WatchEvent, PullRequestEvent, …'), col('created_at', 'timestamp', 'When, UTC'),
        col('actor_id', 'integer', 'Account that did it'), col('actor_login', 'text', 'Account name'), col('repo_id', 'integer', 'Repository'), col('repo_name', 'text', 'owner/name'),
        col('org', 'text', 'Organisation', true), col('action', 'text', 'opened, closed, started, … (not every type has one)', true),
        col('ref', 'text', 'Branch or tag (push, create, delete)', true), col('commits', 'integer', 'Commits in a push', true), col('number', 'integer', 'Issue or pull request number', true),
      ],
    },
    actors: { description: 'One account that appears in the events. Bots included.', primaryKey: ['actor_id'], columns: [col('actor_id', 'integer', 'Account ID'), col('login', 'text', 'Account name'), col('is_bot', 'integer', '1 for bot accounts')] },
    repos: {
      description: 'One repository that appears in the events.',
      primaryKey: ['repo_id'],
      columns: [col('repo_id', 'integer', 'Repository ID'), col('name', 'text', 'owner/name'), col('owner', 'text', 'Owner organisation'), col('language', 'text', 'Main language', true), col('created_at', 'timestamp', 'Created, UTC'), col('stars_before', 'integer', 'Stars before these four weeks')],
    },
  },
  editions: Object.fromEntries(Object.keys(EDITIONS).map(k => [k, k])),
  stress: false,
  generate,
  cutEdition,
  extraFiles,
  realIssues,
};

export default dataset;
